import React, { useState, useEffect } from 'react';
import {
  AreaChart,
  Area,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer
} from 'recharts';

/**
 * Helper to group commits by day.
 * Returns an array of { date: 'YYYY-MM-DD', count: numberOfCommits }
 */
function groupCommitsByDay(dates) {
  const dayMap = {};
  dates.forEach(date => {
    const dayString = date.toISOString().split('T')[0]; // e.g., "2023-06-09"
    if (!dayMap[dayString]) {
      dayMap[dayString] = 0;
    }
    dayMap[dayString]++;
  });

  // Convert the dayMap object into an array
  const result = Object.entries(dayMap).map(([date, count]) => ({ date, count }));
  // Sort by date ascending
  result.sort((a, b) => new Date(a.date) - new Date(b.date));
  return result;
}

const GithubHeartbeat = () => {
  const [commitData, setCommitData] = useState([]);
  const [errorMessage, setErrorMessage] = useState(null);

  useEffect(() => {
    const fetchAllCommits = async () => {
      try {
        // 1. Fetch all public repos for the user (up to 100)
        const reposResponse = await fetch('https://api.github.com/users/ranvirdeshmukh/repos?per_page=100');
        if (!reposResponse.ok) {
          throw new Error(`Error fetching repos: ${reposResponse.status}`);
        }
        const repos = await reposResponse.json();

        // 2. For each repo, fetch up to 100 commits
        let allCommitDates = [];
        for (const repo of repos) {
          // Skip forked repos if you only want commits in your own repositories
          // if (repo.fork) continue;

          const commitsUrl = `https://api.github.com/repos/ranvirdeshmukh/${repo.name}/commits?per_page=100`;
          const commitsResponse = await fetch(commitsUrl);

          // If there's an error or a private repo (without auth), skip it
          if (!commitsResponse.ok) {
            console.warn(`Skipping repo "${repo.name}" due to fetch error: ${commitsResponse.status}`);
            continue;
          }

          const commitsData = await commitsResponse.json();
          if (Array.isArray(commitsData)) {
            // Extract the commit dates from each commit object
            const commitDates = commitsData.map(c => new Date(c.commit.author.date));
            allCommitDates.push(...commitDates);
          }
        }

        // 3. Group all commits by day
        const grouped = groupCommitsByDay(allCommitDates);
        setCommitData(grouped);
      } catch (error) {
        console.error('Error fetching commits:', error);
        setErrorMessage(error.message);
      }
    };

    fetchAllCommits();
  }, []);

  // Optionally compute total commits across all repos
  const totalCommits = commitData.reduce((acc, item) => acc + item.count, 0);

  return (
    <div style={{ marginTop: '40px' }}>
      <h3 style={{ fontFamily: "'SF Pro Display', sans-serif", fontWeight: 500 }}>
        GitHub Heartbeat (All Public Repos)
      </h3>

      {errorMessage && <p style={{ color: 'red' }}>Error: {errorMessage}</p>}

      <p>
        {totalCommits} contributions across all public repositories
      </p>

      {/* ResponsiveContainer will size to the width of its parent container */}
      <div style={{ width: '100%', height: 300 }}>
        <ResponsiveContainer>
          <AreaChart data={commitData}>
            <defs>
              {/* This gradient is for the area fill under the line */}
              <linearGradient id="colorCount" x1="0" y1="0" x2="0" y2="1">
                <stop offset="5%" stopColor="#8884d8" stopOpacity={0.8} />
                <stop offset="95%" stopColor="#8884d8" stopOpacity={0} />
              </linearGradient>
            </defs>
            <CartesianGrid strokeDasharray="3 3" />
            <XAxis dataKey="date" />
            <YAxis />
            <Tooltip />
            <Area
              type="monotone"
              dataKey="count"
              stroke="#8884d8"
              fillOpacity={1}
              fill="url(#colorCount)"
            />
          </AreaChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
};

export default GithubHeartbeat;
